namespace sv_988cb79b0f174029a155329938424e5d.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

using sv_988cb79b0f174029a155329938424e5d.Models;

namespace sv_988cb79b0f174029a155329938424e5d.Services;

public class ApplicationService : IApplicationService
{
    public async Task<int> SubmitApplicationAsync(JobApplication application)
    {
        await Task.Delay(1500);
        return Random.Shared.Next(10000, 99999);
    }

    public async Task<bool> ValidateEmailAsync(string email)
    {
        await Task.Delay(500);
        if (string.IsNullOrWhiteSpace(email)) return false;
        var atIndex = email.IndexOf('@');
        return atIndex > 0 && email.IndexOf('.', atIndex) > atIndex;
    }
}

@using sv_988cb79b0f174029a155329938424e5d.Components.Pages

<div class="card">
    <div class="card-body">
        <h4 class="card-title mb-4">Personal Information</h4>

        <div class="mb-3">
            <label class="form-label">Full Name <span class="text-danger">*</span></label>
            <input type="text" class="form-control @(Attempted && string.IsNullOrWhiteSpace(Model.FullName) ? "is-invalid" : "")"
                   @bind="Model.FullName" @bind:event="oninput" placeholder="John Doe" />
            @if (Attempted && string.IsNullOrWhiteSpace(Model.FullName))
            {
                <div class="invalid-feedback">Full name is required.</div>
            }
        </div>

        <div class="mb-3">
            <label class="form-label">Email <span class="text-danger">*</span></label>
            <input type="email" class="form-control @(Attempted && string.IsNullOrWhiteSpace(Model.Email) ? "is-invalid" : EmailError != null ? "is-invalid" : "")"
                   @bind="Model.Email" @bind:event="oninput" placeholder="john@example.com" />
            @if (Attempted && string.IsNullOrWhiteSpace(Model.Email))
            {
                <div class="invalid-feedback">Email is required.</div>
            }
            else if (EmailError != null)
            {
                <div class="invalid-feedback d-block">@EmailError</div>
            }
            @if (IsValidating)
            {
                <small class="text-muted">Validating email...</small>
            }
        </div>

        <div class="mb-3">
            <label class="form-label">Phone <span class="text-danger">*</span></label>
            <input type="tel" class="form-control @(Attempted && string.IsNullOrWhiteSpace(Model.Phone) ? "is-invalid" : "")"
                   @bind="Model.Phone" @bind:event="oninput" placeholder="(555) 123-4567" />
            @if (Attempted && string.IsNullOrWhiteSpace(Model.Phone))
            {
                <div class="invalid-feedback">Phone is required.</div>
            }
        </div>

        <div class="mb-3">
            <label class="form-label">Address <span class="text-danger">*</span></label>
            <textarea class="form-control @(Attempted && string.IsNullOrWhiteSpace(Model.Address) ? "is-invalid" : "")"
                      @bind="Model.Address" @bind:event="oninput" rows="2" placeholder="123 Main St, City, State ZIP"></textarea>
            @if (Attempted && string.IsNullOrWhiteSpace(Model.Address))
            {
                <div class="invalid-feedback">Address is required.</div>
            }
        </div>

        <div class="d-flex justify-content-end">
            <button class="btn btn-primary" @onclick="HandleNext" disabled="@IsValidating">
                @if (IsValidating)
                {
                    <span class="spinner-border spinner-border-sm me-1"></span>
                }
                Next →
            </button>
        </div>
    </div>
</div>

@code {
    [Parameter] public Apply.PersonalInfoModel Model { get; set; } = default!;
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public string? EmailError { get; set; }
    [Parameter] public EventCallback OnValidateEmail { get; set; }
    [Parameter] public bool IsValidating { get; set; }

    private bool Attempted;

    private async Task HandleNext()
    {
        Attempted = true;

        if (string.IsNullOrWhiteSpace(Model.FullName) ||
            string.IsNullOrWhiteSpace(Model.Email) ||
            string.IsNullOrWhiteSpace(Model.Phone) ||
            string.IsNullOrWhiteSpace(Model.Address))
            return;

        await OnValidateEmail.InvokeAsync();
    }
}

@using sv_988cb79b0f174029a155329938424e5d.Components.Pages

<div class="card">
    <div class="card-body">
        <h4 class="card-title mb-4">Work History</h4>

        @for (int i = 0; i < Entries.Count; i++)
        {
            var index = i;
            var entry = Entries[index];
            <div class="border rounded p-3 mb-3">
                <div class="d-flex justify-content-between align-items-center mb-3">
                    <h6 class="mb-0">Position @(index + 1)</h6>
                    @if (Entries.Count > 1)
                    {
                        <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveEntry(index)">Remove</button>
                    }
                </div>

                <div class="row mb-3">
                    <div class="col-md-6">
                        <label class="form-label">Company <span class="text-danger">*</span></label>
                        <input type="text" class="form-control @(Attempted && string.IsNullOrWhiteSpace(entry.Company) && index == 0 ? "is-invalid" : "")"
                               @bind="entry.Company" @bind:event="oninput" />
                        @if (Attempted && string.IsNullOrWhiteSpace(entry.Company) && index == 0)
                        {
                            <div class="invalid-feedback">Company is required for at least the first entry.</div>
                        }
                    </div>
                    <div class="col-md-6">
                        <label class="form-label">Title <span class="text-danger">*</span></label>
                        <input type="text" class="form-control @(Attempted && string.IsNullOrWhiteSpace(entry.Title) && index == 0 ? "is-invalid" : "")"
                               @bind="entry.Title" @bind:event="oninput" />
                        @if (Attempted && string.IsNullOrWhiteSpace(entry.Title) && index == 0)
                        {
                            <div class="invalid-feedback">Title is required for at least the first entry.</div>
                        }
                    </div>
                </div>

                <div class="row mb-3">
                    <div class="col-md-4">
                        <label class="form-label">Start Date</label>
                        <input type="date" class="form-control" @bind="entry.StartDate" />
                    </div>
                    <div class="col-md-4">
                        @if (!entry.IsCurrent)
                        {
                            <label class="form-label">End Date</label>
                            <input type="date" class="form-control" @bind="entry.EndDate" />
                        }
                    </div>
                    <div class="col-md-4 d-flex align-items-end">
                        <div class="form-check mb-2">
                            <input type="checkbox" class="form-check-input" id="current-@index"
                                   @bind="entry.IsCurrent" />
                            <label class="form-check-label" for="current-@index">Currently working here</label>
                        </div>
                    </div>
                </div>

                <div class="mb-2">
                    <label class="form-label">Description</label>
                    <textarea class="form-control" @bind="entry.Description" @bind:event="oninput" rows="3"></textarea>
                </div>
            </div>
        }

        <button class="btn btn-outline-secondary mb-3" @onclick="AddEntry">+ Add Another Position</button>

        @if (Attempted && !HasValidEntry())
        {
            <div class="alert alert-danger">At least one position must have Company and Title filled in.</div>
        }

        <div class="d-flex justify-content-between">
            <button class="btn btn-secondary" @onclick="OnBack">← Back</button>
            <button class="btn btn-primary" @onclick="HandleNext">Next →</button>
        </div>
    </div>
</div>

@code {
    [Parameter] public List<Apply.WorkEntryModel> Entries { get; set; } = default!;
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private bool Attempted;

    private bool HasValidEntry() =>
        Entries.Any(e => !string.IsNullOrWhiteSpace(e.Company) && !string.IsNullOrWhiteSpace(e.Title));

    private void AddEntry() => Entries.Add(new Apply.WorkEntryModel());

    private void RemoveEntry(int index) => Entries.RemoveAt(index);

    private async Task HandleNext()
    {
        Attempted = true;
        if (!HasValidEntry()) return;
        await OnNext.InvokeAsync();
    }
}

@using sv_988cb79b0f174029a155329938424e5d.Components.Pages

<div class="card">
    <div class="card-body">
        <h4 class="card-title mb-4">References</h4>

        @for (int i = 0; i < References.Count; i++)
        {
            var index = i;
            var reference = References[index];
            <div class="border rounded p-3 mb-3">
                <div class="d-flex justify-content-between align-items-center mb-3">
                    <h6 class="mb-0">Reference @(index + 1)</h6>
                    @if (References.Count > 1)
                    {
                        <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveReference(index)">Remove</button>
                    }
                </div>

                <div class="row mb-3">
                    <div class="col-md-6">
                        <label class="form-label">Name <span class="text-danger">*</span></label>
                        <input type="text" class="form-control @(Attempted && string.IsNullOrWhiteSpace(reference.Name) && index == 0 ? "is-invalid" : "")"
                               @bind="reference.Name" @bind:event="oninput" />
                    </div>
                    <div class="col-md-6">
                        <label class="form-label">Relationship</label>
                        <input type="text" class="form-control" @bind="reference.Relationship" @bind:event="oninput" />
                    </div>
                </div>

                <div class="row mb-2">
                    <div class="col-md-6">
                        <label class="form-label">Email <span class="text-danger">*</span></label>
                        <input type="email" class="form-control @(Attempted && string.IsNullOrWhiteSpace(reference.Email) && index == 0 ? "is-invalid" : "")"
                               @bind="reference.Email" @bind:event="oninput" />
                    </div>
                    <div class="col-md-6">
                        <label class="form-label">Phone</label>
                        <input type="tel" class="form-control" @bind="reference.Phone" @bind:event="oninput" />
                    </div>
                </div>
            </div>
        }

        @if (References.Count < 3)
        {
            <button class="btn btn-outline-secondary mb-3" @onclick="AddReference">+ Add Reference</button>
        }

        @if (Attempted && !HasValidReference())
        {
            <div class="alert alert-danger">At least one reference must have Name and Email filled in.</div>
        }

        <div class="d-flex justify-content-between">
            <button class="btn btn-secondary" @onclick="OnBack">← Back</button>
            <button class="btn btn-primary" @onclick="HandleNext">Next →</button>
        </div>
    </div>
</div>

@code {
    [Parameter] public List<Apply.ReferenceModel> References { get; set; } = default!;
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private bool Attempted;

    private bool HasValidReference() =>
        References.Any(r => !string.IsNullOrWhiteSpace(r.Name) && !string.IsNullOrWhiteSpace(r.Email));

    private void AddReference() => References.Add(new Apply.ReferenceModel());

    private void RemoveReference(int index) => References.RemoveAt(index);

    private async Task HandleNext()
    {
        Attempted = true;
        if (!HasValidReference()) return;
        await OnNext.InvokeAsync();
    }
}

@using sv_988cb79b0f174029a155329938424e5d.Components.Pages

@if (SubmittedApplicationId.HasValue)
{
    <div class="alert alert-success text-center py-5">
        <h3>🎉 Application Submitted!</h3>
        <p class="lead">Your application ID is <strong>#@SubmittedApplicationId</strong></p>
        <p>We'll review your application and get back to you soon.</p>
    </div>
}
else
{
    <div class="card mb-3">
        <div class="card-header d-flex justify-content-between align-items-center">
            <h5 class="mb-0">Personal Information</h5>
            <button class="btn btn-sm btn-outline-primary" @onclick="() => OnEditStep.InvokeAsync(1)">Edit</button>
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-md-6"><strong>Name:</strong> @Personal.FullName</div>
                <div class="col-md-6"><strong>Email:</strong> @Personal.Email</div>
                <div class="col-md-6"><strong>Phone:</strong> @Personal.Phone</div>
                <div class="col-md-6"><strong>Address:</strong> @Personal.Address</div>
            </div>
        </div>
    </div>

    <div class="card mb-3">
        <div class="card-header d-flex justify-content-between align-items-center">
            <h5 class="mb-0">Work History</h5>
            <button class="btn btn-sm btn-outline-primary" @onclick="() => OnEditStep.InvokeAsync(2)">Edit</button>
        </div>
        <div class="card-body">
            @foreach (var entry in WorkEntries.Where(e => !string.IsNullOrWhiteSpace(e.Company)))
            {
                <div class="border-bottom pb-2 mb-2">
                    <strong>@entry.Title</strong> at <strong>@entry.Company</strong><br />
                    <small class="text-muted">
                        @(entry.StartDate?.ToString("MMM yyyy") ?? "N/A") –
                        @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
                    </small>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <p class="mt-1 mb-0">@entry.Description</p>
                    }
                </div>
            }
        </div>
    </div>

    <div class="card mb-3">
        <div class="card-header d-flex justify-content-between align-items-center">
            <h5 class="mb-0">References</h5>
            <button class="btn btn-sm btn-outline-primary" @onclick="() => OnEditStep.InvokeAsync(3)">Edit</button>
        </div>
        <div class="card-body">
            @foreach (var r in References.Where(r => !string.IsNullOrWhiteSpace(r.Name)))
            {
                <div class="border-bottom pb-2 mb-2">
                    <strong>@r.Name</strong>
                    @if (!string.IsNullOrWhiteSpace(r.Relationship))
                    {
                        <span class="text-muted">(@r.Relationship)</span>
                    }
                    <br />
                    <small>@r.Email @(!string.IsNullOrWhiteSpace(r.Phone) ? $"| {r.Phone}" : "")</small>
                </div>
            }
        </div>
    </div>

    <div class="card mb-3">
        <div class="card-header d-flex justify-content-between align-items-center">
            <h5 class="mb-0">Cover Letter</h5>
            <button class="btn btn-sm btn-outline-primary" @onclick="() => OnEditStep.InvokeAsync(4)">Edit</button>
        </div>
        <div class="card-body">
            <p style="white-space: pre-wrap;">@CoverLetterText</p>
        </div>
    </div>

    <div class="d-flex justify-content-between">
        <button class="btn btn-secondary" @onclick="() => OnEditStep.InvokeAsync(4)">← Back</button>
        <button class="btn btn-success btn-lg" @onclick="OnSubmit" disabled="@IsSubmitting">
            @if (IsSubmitting)
            {
                <span class="spinner-border spinner-border-sm me-1"></span>
                <span>Submitting...</span>
            }
            else
            {
                <span>Submit Application</span>
            }
        </button>
    </div>
}

@code {
    [Parameter] public Apply.PersonalInfoModel Personal { get; set; } = default!;
    [Parameter] public List<Apply.WorkEntryModel> WorkEntries { get; set; } = default!;
    [Parameter] public List<Apply.ReferenceModel> References { get; set; } = default!;
    [Parameter] public string CoverLetterText { get; set; } = "";
    [Parameter] public EventCallback<int> OnEditStep { get; set; }
    [Parameter] public EventCallback OnSubmit { get; set; }
    [Parameter] public bool IsSubmitting { get; set; }
    [Parameter] public int? SubmittedApplicationId { get; set; }
}

namespace sv_988cb79b0f174029a155329938424e5d.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

using sv_988cb79b0f174029a155329938424e5d.Models;

namespace sv_988cb79b0f174029a155329938424e5d.Services;

public class ApplicationService : IApplicationService
{
    public async Task<int> SubmitApplicationAsync(JobApplication application)
    {
        await Task.Delay(1500);
        return Random.Shared.Next(10000, 99999);
    }

    public async Task<bool> ValidateEmailAsync(string email)
    {
        await Task.Delay(500);
        if (string.IsNullOrWhiteSpace(email)) return false;
        var atIndex = email.IndexOf('@');
        return atIndex > 0 && email.IndexOf('.', atIndex) > atIndex;
    }
}

