@page "/apply"
@rendermode InteractiveServer
@using sv_988cb79b0f174029a155329938424e5d.Models
@using sv_988cb79b0f174029a155329938424e5d.Components.Pages.ApplySteps
@inject IApplicationService AppService

<PageTitle>Apply</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="mb-4 text-center">Job Application</h2>

    @if (SubmittedApplicationId is null)
    {
        <!-- Step Indicator -->
        <div class="d-flex justify-content-center mb-4">
            <div class="step-indicator d-flex gap-2 flex-wrap justify-content-center">
                @for (int i = 1; i <= StepLabels.Length; i++)
                {
                    var step = i;
                    var label = StepLabels[step - 1];
                    var isCompleted = step < CurrentStep;
                    var isCurrent = step == CurrentStep;
                    var isFuture = step > CurrentStep;

                    <button class="btn @(isCurrent ? "btn-primary" : isCompleted ? "btn-outline-success" : "btn-outline-secondary") step-btn"
                            disabled="@isFuture"
                            @onclick="() => GoToStep(step)">
                        @if (isCompleted)
                        {
                            <span>✓ </span>
                        }
                        <span class="d-none d-md-inline">@label</span>
                        <span class="d-md-none">@step</span>
                    </button>
                }
            </div>
        </div>

        <div class="mb-2 text-center text-muted">
            <small>Step @CurrentStep of @StepLabels.Length — @StepLabels[CurrentStep - 1]</small>
        </div>
    }

    @switch (CurrentStep)
    {
        case 1:
            <StepPersonalInfo Model="PersonalModel"
                              EmailError="@EmailError"
                              IsValidating="@IsValidatingEmail"
                              OnValidateEmail="HandleValidateEmail"
                              OnNext="HandlePersonalNext" />
            break;
        case 2:
            <StepWorkHistory Entries="WorkEntries"
                             OnNext="() => CurrentStep = 3"
                             OnBack="() => CurrentStep = 1" />
            break;
        case 3:
            <StepReferences References="ReferenceList"
                            OnNext="() => CurrentStep = 4"
                            OnBack="() => CurrentStep = 2" />
            break;
        case 4:
            <StepCoverLetter CoverLetterText="@CoverLetterText"
                             CoverLetterTextChanged="val => { CoverLetterText = val; }"
                             OnNext="() => CurrentStep = 5"
                             OnBack="() => CurrentStep = 3" />
            break;
        case 5:
            <StepReview Personal="PersonalModel"
                        WorkEntries="WorkEntries"
                        References="ReferenceList"
                        CoverLetterText="@CoverLetterText"
                        OnEditStep="GoToStep"
                        OnSubmit="HandleSubmit"
                        IsSubmitting="@IsSubmitting"
                        SubmittedApplicationId="@SubmittedApplicationId" />
            break;
    }
</div>

@code {
    private static readonly string[] StepLabels = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    private int CurrentStep { get; set; } = 1;
    private string? EmailError;
    private bool IsValidatingEmail;
    private bool IsSubmitting;
    private int? SubmittedApplicationId;

    // Form state
    private PersonalInfoModel PersonalModel = new();
    private List<WorkEntryModel> WorkEntries = new() { new WorkEntryModel() };
    private List<ReferenceModel> ReferenceList = new() { new ReferenceModel() };
    private string CoverLetterText = "";

    private void GoToStep(int step)
    {
        if (step < CurrentStep || step == CurrentStep)
            CurrentStep = step;
    }

    private async Task HandleValidateEmail()
    {
        EmailError = null;
        IsValidatingEmail = true;
        StateHasChanged();

        var isValid = await AppService.ValidateEmailAsync(PersonalModel.Email);

        IsValidatingEmail = false;

        if (!isValid)
        {
            EmailError = "Please enter a valid email address.";
            StateHasChanged();
            return;
        }

        // Email valid — advance
        await HandlePersonalNext();
    }

    private Task HandlePersonalNext()
    {
        if (EmailError != null) return Task.CompletedTask;
        CurrentStep = 2;
        return Task.CompletedTask;
