                 <div class="col-md-6"><strong>Email:</strong> @Personal.Email</div>
                 <div class="col-md-6"><strong>Phone:</strong> @Personal.Phone</div>
                 <div class="col-md-6"><strong>Address:</strong> @Personal.Address</div>
             </div>
         </div>
     </div>

     <div class="card mb-3">
         <div class="card-header d-flex justify-content-between align-items-center">
             <h5 class="mb-0">Work History</h5>
             <button class="btn btn-sm btn-outline-primary" @onclick="() => OnEditStep.InvokeAsync(2)">Edit</button>
         </div>
         <div class="card-body">
             @foreach (var entry in WorkEntries.Where(e => !string.IsNullOrWhiteSpace(e.Company)))
             {
                 <div class="border-bottom pb-2 mb-2">
                     <strong>@entry.Title</strong> at <strong>@entry.Company</strong><br />
                     <small class="text-muted">
                         @(entry.StartDate?.ToString("MMM yyyy") ?? "N/A") –
                         @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
                     </small>
                     @if (!string.IsNullOrWhiteSpace(entry.Description))
                     {
                         <p class="mt-1 mb-0">@entry.Description</p>
                     }
                 </div>
             }
         </div>
     </div>

     <div class="card mb-3">
         <div class="card-header d-flex justify-content-between align-items-center">
             <h5 class="mb-0">References</h5>
             <button class="btn btn-sm btn-outline-primary" @onclick="() => OnEditStep.InvokeAsync(3)">Edit</button>
         </div>
         <div class="card-body">
             @foreach (var r in References.Where(r => !string.IsNullOrWhiteSpace(r.Name)))
             {
                 <div class="border-bottom pb-2 mb-2">
                     <strong>@r.Name</strong>
                     @if (!string.IsNullOrWhiteSpace(r.Relationship))
                     {
                         <span class="text-muted">(@r.Relationship)</span>
                     }
                     <br />
                     <small>@r.Email @(!string.IsNullOrWhiteSpace(r.Phone) ? $"| {r.Phone}" : "")</small>
                 </div>
             }
         </div>
     </div>

     <div class="card mb-3">
         <div class="card-header d-flex justify-content-between align-items-center">
             <h5 class="mb-0">Cover Letter</h5>
             <button class="btn btn-sm btn-outline-primary" @onclick="() => OnEditStep.InvokeAsync(4)">Edit</button>
         </div>
         <div class="card-body">
             <p style="white-space: pre-wrap;">@CoverLetterText</p>
         </div>
     </div>

     <div class="d-flex justify-content-between">
         <button class="btn btn-secondary" @onclick="() => OnEditStep.InvokeAsync(4)">← Back</button>
         <button class="btn btn-success btn-lg" @onclick="OnSubmit" disabled="@IsSubmitting">
             @if (IsSubmitting)
             {
                 <span class="spinner-border spinner-border-sm me-1"></span>
                 <span>Submitting...</span>
             }
             else
             {
                 <span>Submit Application</span>
             }
         </button>
     </div>
 }

